Lemma munch_appx : forall (A B : list (Z * Z)) m1 m2 m3, munch A m1 m2 -> munch B m2 m3 -> munch (A ++ B) m1 m3.
Proof.
  intros A B m1 m2 m3 M1 M2. eapply munch_trans; (eapply munch_weaken; [| eassumption]); intros x Hx; apply outside_appx in Hx; tauto.
Qed.

